  "answer": {
    "definition": {
      "optimistic_lock": "乐观锁假设并发冲突较少，通过版本号（version）或时间戳（timestamp）实现，适用于读多写少的场景。",
      "pessimistic_lock": "悲观锁假设并发冲突频繁，通过锁机制（如数据库行锁、分布式锁）实现，适用于高并发写操作的场景。"
    },
    "differences": {
      "core_difference": "乐观锁不加锁，依赖版本控制；悲观锁加锁，直接阻塞其他操作。",
      "implementation_method": "乐观锁：版本号/时间戳；悲观锁：数据库行锁/分布式锁（如Redis锁）。",
      "suitable_scenarios": "乐观锁：库存系统、读多写少场景；悲观锁：银行交易、高并发写场景。"
    },
    "application_scenarios": {
      "optimistic_lock": "读多写少场景（如电商商品库存），避免锁竞争。",
      "pessimistic_lock": "高并发写场景（如银行转账），确保数据一致性。"
    }
  }
}
